// for_locking_item+
func (p *parser) e2994() (*Node, bool) {
	start := p.pos
	base := len(p.kidStack)
	count := 0
	for {
		m0 := p.mark()
		prevCut, prevFrame := p.cut, p.frame
		p.cut = false
		v, ok := p.e2993()
		cut := p.cut
		p.cut, p.frame = prevCut, prevFrame
		if !ok {
			p.reset(m0)
			if cut {
				p.dropKids(base)
				return nil, false
			}
			break
		}
		count++
		p.kidStack = append(p.kidStack, v)
		if p.pos == m0.pos && count >= 1 {
			break
		}
	}
	if count < 1 {
		p.dropKids(base)
		return nil, false
	}
	return p.newNode(Node{kind: kindList, Start: int32(start), End: int32(p.pos), Children: p.kids(base), fresh: true}), true
}

