// (-COMMA x:returning_option)* (projected to x)
func (p *parser) e3835() (*Node, bool) {
	start := p.pos
	base := len(p.kidStack)
	f := p.newFrame(1)
	count := 0
	for {
		clear(f.vals)
		m0 := p.mark()
		prevCut, prevFrame := p.cut, p.frame
		p.cut = false
		p.frame = f
		_, ok := p.e3834()
		cut := p.cut
		p.cut, p.frame = prevCut, prevFrame
		if !ok {
			p.reset(m0)
			if cut {
				p.dropKids(base)
				return nil, false
			}
			break
		}
		count++
		p.kidStack = append(p.kidStack, f.vals[0])
		if p.pos == m0.pos && count >= 0 {
			break
		}
	}
	if count < 0 {
		p.dropKids(base)
		return nil, false
	}
	return p.newNode(Node{kind: kindList, Start: int32(start), End: int32(p.pos), Children: p.kids(base), fresh: true}), true
}

