// (-COMMA x:returning_option)*
func (p *parser) e21305() (*Node, bool) {
	start := p.pos
	base := len(p.kidStack)
	count := 0
	for {
		m0 := p.mark()
		prevCut, prevFrame := p.cut, p.frame
		p.cut = false
		f := p.newFrame(1)
		p.frame = f
		v, ok := p.e21303()
		cut := p.cut
		p.cut, p.frame = prevCut, prevFrame
		if !ok {
			p.reset(m0)
			if cut {
				p.dropKids(base)
				return nil, false
			}
			break
		}
		v = p.attachCaptures(v, scope21304, f, m0.pos, p.pos)
		count++
		p.kidStack = append(p.kidStack, v)
		if p.pos == m0.pos && count >= 0 {
			break
		}
	}
	if count < 0 {
		p.dropKids(base)
		return nil, false
	}
	return p.newNode(Node{kind: kindList, Start: int32(start), End: int32(p.pos), Children: p.kids(base), fresh: true}), true
}

